"use client";

import {
  Fragment,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type CSSProperties,
  type DragEvent,
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
} from "react";

import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@/components/ui/tabs";
import {
  computeTabWindowsDropEdge,
  moveTabWindowsTab,
  normalizeTabWindowsSizes,
  setTabWindowsActiveTab,
  setTabWindowsSizesAtPath,
  type TabWindowsDropEdge,
  type TabWindowsLayout,
  type TabWindowsPane,
  type TabWindowsSplit,
} from "@/lib/tab-windows-layout";
import { cn } from "@/lib/utils";

interface DragState<TTab extends string> {
  sourcePaneId: string;
  tab: TTab;
}

interface ResizeState {
  path: number[];
  index: number;
  direction: "horizontal" | "vertical";
  startClient: number;
  startSizes: number[];
  extent: number;
}

export interface TabWindowsProps<TTab extends string = string> {
  defaultLayout: TabWindowsLayout<TTab>;
  layout?: TabWindowsLayout<TTab>;
  onLayoutChange?: (layout: TabWindowsLayout<TTab>) => void;
  renderPanel: (tab: TTab) => ReactNode;
  renderTabLabel?: (tab: TTab) => ReactNode;
  minPaneSize?: number;
  className?: string;
  style?: CSSProperties;
  "aria-label"?: string;
}

export function TabWindows<TTab extends string = string>({
  defaultLayout,
  layout,
  onLayoutChange,
  renderPanel,
  renderTabLabel,
  minPaneSize = 140,
  className,
  style,
  "aria-label": ariaLabel = "Workspace",
}: TabWindowsProps<TTab>) {
  const [internalLayout, setInternalLayout] = useState(defaultLayout);
  const [drag, setDrag] = useState<DragState<TTab> | null>(null);
  const [dropTarget, setDropTarget] = useState<{
    paneId: string;
    edge: TabWindowsDropEdge;
  } | null>(null);
  const [resize, setResize] = useState<ResizeState | null>(null);
  const instanceId = useId().replace(/:/g, "");
  const paneCounter = useRef(0);
  const currentLayout = layout ?? internalLayout;

  const updateLayout = useCallback(
    (update: (current: TabWindowsLayout<TTab>) => TabWindowsLayout<TTab>) => {
      const next = update(layout ?? internalLayout);
      if (layout === undefined) setInternalLayout(next);
      onLayoutChange?.(next);
    },
    [internalLayout, layout, onLayoutChange],
  );

  useEffect(() => {
    if (!resize) return;

    function onPointerMove(event: PointerEvent) {
      if (!resize) return;
      const client =
        resize.direction === "horizontal" ? event.clientX : event.clientY;
      const sizes = [...resize.startSizes];
      const first = sizes[resize.index] ?? 0;
      const second = sizes[resize.index + 1] ?? 0;
      const total = first + second;
      const minimum = Math.min(total / 2, minPaneSize / resize.extent);
      const nextFirst = Math.min(
        Math.max(first + (client - resize.startClient) / resize.extent, minimum),
        total - minimum,
      );
      sizes[resize.index] = nextFirst;
      sizes[resize.index + 1] = total - nextFirst;
      updateLayout((current) =>
        setTabWindowsSizesAtPath(current, resize.path, sizes),
      );
    }

    function stopResize() {
      setResize(null);
    }

    window.addEventListener("pointermove", onPointerMove);
    window.addEventListener("pointerup", stopResize);
    window.addEventListener("pointercancel", stopResize);
    return () => {
      window.removeEventListener("pointermove", onPointerMove);
      window.removeEventListener("pointerup", stopResize);
      window.removeEventListener("pointercancel", stopResize);
    };
  }, [minPaneSize, resize, updateLayout]);

  function renderNode(node: TabWindowsLayout<TTab>, path: number[]): ReactNode {
    return node.type === "pane" ? renderPane(node) : renderSplit(node, path);
  }

  function renderSplit(node: TabWindowsSplit<TTab>, path: number[]) {
    const sizes = normalizeTabWindowsSizes(node.sizes, node.children.length);
    return (
      <div
        data-slot="tab-windows-split"
        data-direction={node.direction}
        className={cn(
          "flex size-full min-h-0 min-w-0 overflow-hidden",
          node.direction === "horizontal" ? "flex-row" : "flex-col",
        )}
      >
        {node.children.map((child, index) => (
          <Fragment key={`${path.join(".")}-${index}-${nodeKey(child)}`}>
            <div
              className="min-h-0 min-w-0 overflow-hidden"
              style={{ flex: `${sizes[index]} 1 0px` }}
            >
              {renderNode(child, [...path, index])}
            </div>
            {index < node.children.length - 1 ? (
              <div
                aria-label="Resize pane"
                aria-orientation={
                  node.direction === "horizontal" ? "vertical" : "horizontal"
                }
                aria-valuemin={0}
                aria-valuemax={100}
                aria-valuenow={Math.round((sizes[index] ?? 0) * 100)}
                className={cn(
                  "z-10 shrink-0 outline-none",
                  node.direction === "horizontal"
                    ? "w-1 cursor-col-resize"
                    : "h-1 cursor-row-resize",
                )}
                onKeyDown={(event) =>
                  resizeWithKeyboard(event, node, path, index)
                }
                onPointerDown={(event) =>
                  startResize(event, node, path, index)
                }
                role="separator"
                data-slot="tab-windows-resize-handle"
                tabIndex={0}
              />
            ) : null}
          </Fragment>
        ))}
      </div>
    );
  }

  function renderPane(pane: TabWindowsPane<TTab>) {
    const activeDrop =
      dropTarget?.paneId === pane.id ? dropTarget.edge : undefined;
    return (
      <section
        className="relative flex size-full min-h-0 min-w-0 flex-col overflow-hidden"
        data-drop-edge={activeDrop}
        data-pane-id={pane.id}
        data-slot="tab-windows-pane"
        onDragLeave={(event) => {
          const next = event.relatedTarget;
          if (!(next instanceof Node) || !event.currentTarget.contains(next)) {
            setDropTarget(null);
          }
        }}
        onDragOver={(event) => updateDropTarget(event, pane.id)}
        onDrop={(event) => applyDrop(event, pane.id)}
      >
        <Tabs
          className="flex size-full min-h-0 flex-col"
          value={pane.activeTab}
          onValueChange={(value) => {
            if (typeof value !== "string") return;
            updateLayout((current) =>
              setTabWindowsActiveTab(current, pane.id, value as TTab),
            );
          }}
        >
          <TabsList
            aria-label={`${pane.id} tabs`}
            className="flex shrink-0"
          >
            {pane.tabs.map((tab) => (
              <TabsTrigger
                className="cursor-grab select-none"
                data-slot="tab-windows-tab"
                draggable
                key={tab}
                onDragEnd={clearDrag}
                onDragStart={(event) => startDrag(event, pane.id, tab)}
                value={tab}
              >
                {renderTabLabel?.(tab) ?? tab}
              </TabsTrigger>
            ))}
          </TabsList>
          <TabsContent
            className="min-h-0 flex-1 overflow-auto outline-none"
            data-slot="tab-windows-panel"
            value={pane.activeTab}
          >
            {renderPanel(pane.activeTab)}
          </TabsContent>
        </Tabs>
        {activeDrop ? (
          <div
            aria-hidden="true"
            className={dropIndicatorClass(activeDrop)}
            data-drop-edge={activeDrop}
            data-slot="tab-windows-drop-indicator"
          />
        ) : null}
      </section>
    );
  }

  function startDrag(
    event: DragEvent<HTMLButtonElement>,
    sourcePaneId: string,
    tab: TTab,
  ) {
    event.dataTransfer.effectAllowed = "move";
    event.dataTransfer.setData("text/plain", `${sourcePaneId}:${tab}`);
    setDrag({ sourcePaneId, tab });
  }

  function clearDrag() {
    setDrag(null);
    setDropTarget(null);
  }

  function updateDropTarget(event: DragEvent<HTMLElement>, paneId: string) {
    if (!drag) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
    setDropTarget({
      paneId,
      edge: computeTabWindowsDropEdge(
        { x: event.clientX, y: event.clientY },
        event.currentTarget.getBoundingClientRect(),
      ),
    });
  }

  function applyDrop(event: DragEvent<HTMLElement>, targetPaneId: string) {
    if (!drag) return;
    event.preventDefault();
    paneCounter.current += 1;
    const edge =
      dropTarget?.paneId === targetPaneId ? dropTarget.edge : "center";
    updateLayout((current) =>
      moveTabWindowsTab(current, {
        ...drag,
        targetPaneId,
        edge,
        newPaneId: `pane-${instanceId}-${paneCounter.current}`,
      }),
    );
    clearDrag();
  }

  function resizeInfo(
    element: HTMLElement,
    node: TabWindowsSplit<TTab>,
    path: number[],
    index: number,
  ): Omit<ResizeState, "startClient"> | null {
    const rect = element.parentElement?.getBoundingClientRect();
    if (!rect) return null;
    return {
      path,
      index,
      direction: node.direction,
      startSizes: normalizeTabWindowsSizes(node.sizes, node.children.length),
      extent: Math.max(
        1,
        node.direction === "horizontal" ? rect.width : rect.height,
      ),
    };
  }

  function startResize(
    event: ReactPointerEvent<HTMLDivElement>,
    node: TabWindowsSplit<TTab>,
    path: number[],
    index: number,
  ) {
    const info = resizeInfo(event.currentTarget, node, path, index);
    if (!info) return;
    event.preventDefault();
    event.currentTarget.setPointerCapture?.(event.pointerId);
    setResize({
      ...info,
      startClient:
        node.direction === "horizontal" ? event.clientX : event.clientY,
    });
  }

  function resizeWithKeyboard(
    event: KeyboardEvent<HTMLDivElement>,
    node: TabWindowsSplit<TTab>,
    path: number[],
    index: number,
  ) {
    const decrease = node.direction === "horizontal" ? "ArrowLeft" : "ArrowUp";
    const increase = node.direction === "horizontal" ? "ArrowRight" : "ArrowDown";
    if (event.key !== decrease && event.key !== increase) return;
    const sizes = normalizeTabWindowsSizes(node.sizes, node.children.length);
    const pair = (sizes[index] ?? 0) + (sizes[index + 1] ?? 0);
    const delta = (event.key === increase ? 1 : -1) * (event.shiftKey ? 0.1 : 0.02);
    const next = Math.min(Math.max((sizes[index] ?? 0) + delta, 0.1), pair - 0.1);
    sizes[index] = next;
    sizes[index + 1] = pair - next;
    event.preventDefault();
    updateLayout((current) => setTabWindowsSizesAtPath(current, path, sizes));
  }

  return (
    <div
      aria-label={ariaLabel}
      className={cn(
        "flex size-full min-h-0 min-w-0 overflow-hidden",
        resize && "select-none",
        className,
      )}
      data-slot="tab-windows"
      role="region"
      style={style}
    >
      {renderNode(currentLayout, [])}
    </div>
  );
}

function nodeKey<TTab extends string>(node: TabWindowsLayout<TTab>) {
  return node.type === "pane" ? node.id : node.direction;
}

function dropIndicatorClass(edge: TabWindowsDropEdge) {
  return cn(
    "pointer-events-none absolute z-20 rounded-md border-2 border-primary/70 bg-primary/15 shadow-sm",
    edge === "center" && "inset-2",
    edge === "left" && "inset-y-2 left-2 w-[calc(50%-0.5rem)]",
    edge === "right" && "inset-y-2 right-2 w-[calc(50%-0.5rem)]",
    edge === "top" && "inset-x-2 top-2 h-[calc(50%-0.5rem)]",
    edge === "bottom" && "inset-x-2 bottom-2 h-[calc(50%-0.5rem)]",
  );
}

export type {
  TabWindowsDropEdge,
  TabWindowsLayout,
  TabWindowsPane,
  TabWindowsSplit,
};

import { Tabs as TabsPrimitive } from "@base-ui/react/tabs"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

function Tabs({
  className,
  orientation = "horizontal",
  ...props
}: TabsPrimitive.Root.Props) {
  return (
    <TabsPrimitive.Root
      data-slot="tabs"
      data-orientation={orientation}
      className={cn(
        "group/tabs flex gap-2 data-horizontal:flex-col",
        className
      )}
      {...props}
    />
  )
}

const tabsListVariants = cva(
  "group/tabs-list inline-flex w-fit items-center justify-center rounded-lg p-[3px] text-muted-foreground group-data-horizontal/tabs:h-8 group-data-vertical/tabs:h-fit group-data-vertical/tabs:flex-col data-[variant=line]:rounded-none",
  {
    variants: {
      variant: {
        default: "bg-muted",
        line: "gap-1 bg-transparent",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
)

function TabsList({
  className,
  variant = "default",
  ...props
}: TabsPrimitive.List.Props & VariantProps<typeof tabsListVariants>) {
  return (
    <TabsPrimitive.List
      data-slot="tabs-list"
      data-variant={variant}
      className={cn(tabsListVariants({ variant }), className)}
      {...props}
    />
  )
}

function TabsTrigger({ className, ...props }: TabsPrimitive.Tab.Props) {
  return (
    <TabsPrimitive.Tab
      data-slot="tabs-trigger"
      className={cn(
        "relative inline-flex h-[calc(100%-1px)] flex-1 items-center justify-center gap-1.5 rounded-md border border-transparent px-1.5 py-0.5 text-sm font-medium whitespace-nowrap text-foreground/60 transition-all group-data-vertical/tabs:w-full group-data-vertical/tabs:justify-start hover:text-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:outline-1 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50 has-data-[icon=inline-end]:pr-1 has-data-[icon=inline-start]:pl-1 aria-disabled:pointer-events-none aria-disabled:opacity-50 dark:text-muted-foreground dark:hover:text-foreground group-data-[variant=default]/tabs-list:data-active:shadow-sm group-data-[variant=line]/tabs-list:data-active:shadow-none [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        "group-data-[variant=line]/tabs-list:bg-transparent group-data-[variant=line]/tabs-list:data-active:bg-transparent dark:group-data-[variant=line]/tabs-list:data-active:border-transparent dark:group-data-[variant=line]/tabs-list:data-active:bg-transparent",
        "data-active:bg-background data-active:text-foreground dark:data-active:border-input dark:data-active:bg-input/30 dark:data-active:text-foreground",
        "after:absolute after:bg-foreground after:opacity-0 after:transition-opacity group-data-horizontal/tabs:after:inset-x-0 group-data-horizontal/tabs:after:bottom-[-5px] group-data-horizontal/tabs:after:h-0.5 group-data-vertical/tabs:after:inset-y-0 group-data-vertical/tabs:after:-right-1 group-data-vertical/tabs:after:w-0.5 group-data-[variant=line]/tabs-list:data-active:after:opacity-100",
        className
      )}
      {...props}
    />
  )
}

function TabsContent({ className, ...props }: TabsPrimitive.Panel.Props) {
  return (
    <TabsPrimitive.Panel
      data-slot="tabs-content"
      className={cn("flex-1 text-sm outline-none", className)}
      {...props}
    />
  )
}

export { Tabs, TabsList, TabsTrigger, TabsContent, tabsListVariants }

export type TabWindowsDropEdge =
  | "top"
  | "right"
  | "bottom"
  | "left"
  | "center";

export type TabWindowsSplitDirection = "horizontal" | "vertical";

export interface TabWindowsPane<TTab extends string = string> {
  type: "pane";
  id: string;
  tabs: TTab[];
  activeTab: TTab;
}

export interface TabWindowsSplit<TTab extends string = string> {
  type: "split";
  direction: TabWindowsSplitDirection;
  children: TabWindowsLayout<TTab>[];
  sizes?: number[];
}

export type TabWindowsLayout<TTab extends string = string> =
  | TabWindowsPane<TTab>
  | TabWindowsSplit<TTab>;

export function normalizeTabWindowsSizes(
  sizes: number[] | undefined,
  count: number,
): number[] {
  if (count <= 0) return [];
  const values = Array.from({ length: count }, (_, index) => {
    const value = sizes?.[index];
    return value !== undefined && Number.isFinite(value) && value > 0
      ? value
      : 1;
  });
  const total = values.reduce((sum, value) => sum + value, 0);
  return values.map((value) => value / total);
}

export function findTabWindowsPane<TTab extends string>(
  layout: TabWindowsLayout<TTab>,
  paneId: string,
): TabWindowsPane<TTab> | null {
  if (layout.type === "pane") return layout.id === paneId ? layout : null;
  for (const child of layout.children) {
    const pane = findTabWindowsPane(child, paneId);
    if (pane) return pane;
  }
  return null;
}

export function setTabWindowsActiveTab<TTab extends string>(
  layout: TabWindowsLayout<TTab>,
  paneId: string,
  tab: TTab,
): TabWindowsLayout<TTab> {
  if (layout.type === "pane") {
    return layout.id === paneId && layout.tabs.includes(tab)
      ? { ...layout, activeTab: tab }
      : layout;
  }
  return {
    ...layout,
    children: layout.children.map((child) =>
      setTabWindowsActiveTab(child, paneId, tab),
    ),
  };
}

export function setTabWindowsSizesAtPath<TTab extends string>(
  layout: TabWindowsLayout<TTab>,
  path: number[],
  sizes: number[],
): TabWindowsLayout<TTab> {
  if (path.length === 0) {
    return layout.type === "split"
      ? {
          ...layout,
          sizes: normalizeTabWindowsSizes(sizes, layout.children.length),
        }
      : layout;
  }
  if (layout.type !== "split") return layout;
  const [head, ...tail] = path;
  return {
    ...layout,
    children: layout.children.map((child, index) =>
      index === head ? setTabWindowsSizesAtPath(child, tail, sizes) : child,
    ),
  };
}

function collapseSplit<TTab extends string>(
  split: TabWindowsSplit<TTab>,
): TabWindowsLayout<TTab> | null {
  if (split.children.length === 0) return null;
  if (split.children.length === 1) return split.children[0] ?? null;
  return {
    ...split,
    sizes: normalizeTabWindowsSizes(split.sizes, split.children.length),
  };
}

function removeTab<TTab extends string>(
  layout: TabWindowsLayout<TTab>,
  paneId: string,
  tab: TTab,
): TabWindowsLayout<TTab> | null {
  if (layout.type === "pane") {
    if (layout.id !== paneId) return layout;
    const tabs = layout.tabs.filter((item) => item !== tab);
    if (tabs.length === 0) return null;
    return {
      ...layout,
      tabs,
      activeTab: layout.activeTab === tab ? tabs[0]! : layout.activeTab,
    };
  }
  const children = layout.children
    .map((child) => removeTab(child, paneId, tab))
    .filter((child): child is TabWindowsLayout<TTab> => child !== null);
  return collapseSplit({ ...layout, children });
}

function insertPane<TTab extends string>(
  layout: TabWindowsLayout<TTab>,
  targetPaneId: string,
  pane: TabWindowsPane<TTab>,
  edge: TabWindowsDropEdge,
): TabWindowsLayout<TTab> {
  if (layout.type === "pane") {
    if (layout.id !== targetPaneId) return layout;
    if (edge === "center") {
      const tabs = [...layout.tabs];
      for (const tab of pane.tabs) if (!tabs.includes(tab)) tabs.push(tab);
      return { ...layout, tabs, activeTab: pane.activeTab };
    }
    const direction =
      edge === "left" || edge === "right" ? "horizontal" : "vertical";
    const children =
      edge === "left" || edge === "top" ? [pane, layout] : [layout, pane];
    return { type: "split", direction, children, sizes: [0.5, 0.5] };
  }
  return {
    ...layout,
    children: layout.children.map((child) =>
      insertPane(child, targetPaneId, pane, edge),
    ),
  };
}

export function moveTabWindowsTab<TTab extends string>(
  layout: TabWindowsLayout<TTab>,
  options: {
    tab: TTab;
    sourcePaneId: string;
    targetPaneId: string;
    edge: TabWindowsDropEdge;
    newPaneId: string;
  },
): TabWindowsLayout<TTab> {
  const source = findTabWindowsPane(layout, options.sourcePaneId);
  if (!source?.tabs.includes(options.tab)) return layout;
  if (options.sourcePaneId === options.targetPaneId) {
    if (options.edge === "center") {
      return setTabWindowsActiveTab(layout, options.sourcePaneId, options.tab);
    }
    if (source.tabs.length === 1) return layout;
  }
  const withoutTab = removeTab(layout, options.sourcePaneId, options.tab);
  if (!withoutTab || !findTabWindowsPane(withoutTab, options.targetPaneId)) {
    return layout;
  }
  return insertPane(
    withoutTab,
    options.targetPaneId,
    {
      type: "pane",
      id: options.newPaneId,
      tabs: [options.tab],
      activeTab: options.tab,
    },
    options.edge,
  );
}

export function computeTabWindowsDropEdge(
  point: { x: number; y: number },
  rect: { left: number; top: number; width: number; height: number },
  threshold = 0.24,
): TabWindowsDropEdge {
  if (rect.width <= 0 || rect.height <= 0) return "center";
  const x = Math.min(Math.max((point.x - rect.left) / rect.width, 0), 1);
  const y = Math.min(Math.max((point.y - rect.top) / rect.height, 0), 1);
  const edges: Array<[Exclude<TabWindowsDropEdge, "center">, number]> = [
    ["left", x],
    ["right", 1 - x],
    ["top", y],
    ["bottom", 1 - y],
  ];
  const nearest = edges.reduce((best, edge) =>
    edge[1] < best[1] ? edge : best,
  );
  return nearest[1] <= threshold ? nearest[0] : "center";
}
